-- Six V44 context tables: AUTHORED_NOT_EXECUTED. Original source rows/IDs/SHA/JSON remain unchanged.
-- Run on one admitted ECS connection, distinct schemas, frozen writers, real complete target baseline.
-- Caller must establish @compact_context_source_frozen=1 and @compact_context_target_frozen=1
-- from the reviewed migration window; these flags are assertions, not proof of a write freeze.
-- First SQL error requires same-connection ROLLBACK and close. Never --force.
-- JSON_ARRAY is deliberately not used for original Java digests. Native-MySQL/Java parity is an ECS gate.
SET NAMES utf8mb4;
CREATE TEMPORARY TABLE compact_context_guard(valid INT NOT NULL CHECK(valid=1)) ENGINE=InnoDB;
CREATE TEMPORARY TABLE compact_context_columns(table_name VARCHAR(64),column_name VARCHAR(64),position_no INT,column_type VARCHAR(64),nullable VARCHAR(3),collation_name VARCHAR(64),default_value VARCHAR(64),extra VARCHAR(64),PRIMARY KEY(table_name,column_name)) ENGINE=InnoDB;
CREATE TEMPORARY TABLE compact_context_keys(table_name VARCHAR(64),non_unique INT,is_primary INT,key_columns VARCHAR(1024)) ENGINE=InnoDB;
CREATE TEMPORARY TABLE compact_context_sequences AS SELECT table_name,auto_increment FROM information_schema.tables WHERE table_schema='__SOURCE_SCHEMA__' AND table_name IN ('agent_context_head','agent_context_summary','agent_context_offload','agent_context_audit','agent_context_origin','agent_context_bootstrap');
START TRANSACTION;
UPDATE content_asset t JOIN `__SOURCE_SCHEMA__`.agent_context_summary s ON t.legacy_source='agent_context_summary' AND t.legacy_id=s.id AND t.asset_kind='CONTEXT_SUMMARY' SET t.current_version=1,t.lifecycle=s.status;
COMMIT;
-- Original SHA/JSON/time and NULL-safe ordinary-column checks are executed again after every insert.
