INSERT INTO runtime_state(namespace,owner_id,scope_key,session_id,state_key,revision,current_ref,payload_version,payload_json,created_at,updated_at) SELECT 'CONTEXT_HEAD',s.user_id,SHA2(CONCAT(OCTET_LENGTH(RTRIM(s.session_id)),':',RTRIM(s.session_id),':',OCTET_LENGTH(RTRIM(s.agent_scope)),':',RTRIM(s.agent_scope)),256),s.session_id,s.agent_scope,s.revision,s.summary_id,1,JSON_OBJECT('legacySource','agent_context_head'),NULL,NULL FROM `__SOURCE_SCHEMA__`.agent_context_head s ORDER BY s.user_id,s.session_id,s.agent_scope;
INSERT INTO runtime_state(namespace,owner_id,scope_key,session_id,state_key,revision,counter_value,state_code,payload_version,payload_json,created_at,updated_at) SELECT 'CONTEXT_BOOTSTRAP',s.user_id,SHA2(CONCAT(OCTET_LENGTH(RTRIM(s.session_id)),':',RTRIM(s.session_id),':',OCTET_LENGTH(RTRIM(s.logical_task_id)),':',RTRIM(s.logical_task_id)),256),s.session_id,s.logical_task_id,0,s.history_through,IF(s.initialized=1,'INITIALIZED','RESERVED'),1,JSON_OBJECT('agentScope',s.agent_scope,'initialState',s.initial_state,'initialSha256',s.initial_sha256,'legacySource','agent_context_bootstrap'),NULL,NULL FROM `__SOURCE_SCHEMA__`.agent_context_bootstrap s ORDER BY s.user_id,s.session_id,s.logical_task_id;
INSERT INTO content_asset(asset_id,asset_kind,owner_user_id,identity_key,title,visibility,lifecycle,created_at,updated_at,legacy_source,legacy_id) SELECT CONCAT('context-summary:',s.summary_id),'CONTEXT_SUMMARY',s.user_id,s.summary_id,'持久上下文摘要','PRIVATE','PREPARING',CONVERT_TZ(s.created_at,'__SOURCE_CONTEXT_OFFSET__','+00:00'),NULL,'agent_context_summary',s.id FROM `__SOURCE_SCHEMA__`.agent_context_summary s ORDER BY s.id;
INSERT INTO content_revision(asset_id,asset_kind,version,owner_user_id,content_text,content_sha256,sources_json,source_run_id,manifest_json,created_at,legacy_source,legacy_id) SELECT CONCAT('context-summary:',s.summary_id),'CONTEXT_SUMMARY',1,s.user_id,s.summary_json,s.summary_sha256,s.sources_json,s.run_id,JSON_OBJECT('schemaVersion',1,'sessionId',s.session_id,'agentScope',s.agent_scope,'contextRevision',s.revision,'coveredThrough',s.covered_through,'historySha256',s.history_sha256,'messageState',s.message_state,'policyVersion',s.policy_version,'beforeChars',s.before_chars,'afterChars',s.after_chars,'originalState',s.original_state,'createdAtSource',DATE_FORMAT(s.created_at,'%Y-%m-%d %H:%i:%s.%f'),'sourceUtcOffset','__SOURCE_CONTEXT_OFFSET__'),CONVERT_TZ(s.created_at,'__SOURCE_CONTEXT_OFFSET__','+00:00'),'agent_context_summary',s.id FROM `__SOURCE_SCHEMA__`.agent_context_summary s ORDER BY s.id;
INSERT INTO content_link(link_kind,owner_user_id,session_id,agent_scope,call_id,logical_task_id,run_id,target_type,target_id,evidence_version,evidence_json,created_at,legacy_source) SELECT 'TOOL_SOURCE',s.user_id,s.session_id,s.agent_scope,s.call_key,s.logical_task_id,s.run_id,'CONTEXT_TASK',s.logical_task_id,1,JSON_OBJECT('sourcesJson',s.sources_json,'sourcesSha256',s.sources_sha256),NULL,'agent_context_origin' FROM `__SOURCE_SCHEMA__`.agent_context_origin s ORDER BY s.user_id,s.session_id,s.agent_scope,s.call_key;
INSERT INTO content_link(link_kind,owner_user_id,session_id,agent_scope,call_id,target_type,target_id,subject_type,subject_id,evidence_version,evidence_json,created_at,legacy_source,legacy_id) SELECT 'CONTEXT_SOURCE',s.user_id,s.session_id,s.agent_scope,s.call_id,'WORKSPACE_FILE',s.file_id,'CONTEXT_OFFLOAD',s.offload_id,1,JSON_OBJECT('contentSha256',s.content_sha256,'byteLength',s.byte_length,'sourcesJson',s.sources_json,'sourcesSha256',s.sources_sha256,'createdAtSource',DATE_FORMAT(s.created_at,'%Y-%m-%d %H:%i:%s.%f'),'sourceUtcOffset','__SOURCE_CONTEXT_OFFSET__','lineageKind','LEGACY','sourceOffloadId',NULL,'sourceSessionId',NULL,'throughMessageId',NULL),CONVERT_TZ(s.created_at,'__SOURCE_CONTEXT_OFFSET__','+00:00'),'agent_context_offload',s.id FROM `__SOURCE_SCHEMA__`.agent_context_offload s ORDER BY s.id;
INSERT INTO audit_event(event_id,kind,owner_user_id,resource_type,resource_id,session_id,action,content_sha256,occurred_at,payload_version,payload_json,legacy_source,legacy_key) SELECT CONCAT('legacy-context-audit-',s.id),'CONTEXT',s.user_id,'CONTEXT',s.resource_id,s.session_id,s.action,s.content_sha256,CONVERT_TZ(s.created_at,'__SOURCE_CONTEXT_OFFSET__','+00:00'),1,JSON_OBJECT('agentScope',s.agent_scope,'createdAtSource',DATE_FORMAT(s.created_at,'%Y-%m-%d %H:%i:%s.%f'),'sourceUtcOffset','__SOURCE_CONTEXT_OFFSET__'),'agent_context_audit',CAST(s.id AS CHAR) FROM `__SOURCE_SCHEMA__`.agent_context_audit s ORDER BY s.id;
